.pkgenv <- new.env(parent = emptyenv())

login_helper <- function(auth) {
  if (Sys.getenv("ECONDATA_CREDENTIALS") != "") {
    creds <- unlist(strsplit(Sys.getenv("ECONDATA_CREDENTIALS"), ";"))
    response <- POST(auth$url,
                     path = auth$path,
                     body = list(grant_type = "client_credentials",
                                 client_id = creds[1],
                                 client_secret = creds[2]),
                     encode = "form",
                     accept_json())
    if (response$status_code != 200)
      stop(content(response))
    token <- content(response)$access_token
  } else {
    token <- econdata_credentials()
  }
  assign("econdata_token", paste("Bearer", token), envir = .pkgenv)
}

read_dataset <- function(id, tidy = TRUE, ...) {


  # Parameters ----

  params <- list(...)
  if (is.null(params$debug)) {
    params$debug <- FALSE
  }
  if (!is.null(params$agencyid)) {
    agencyid  <- params$agencyid
  } else {
    agencyid <- "ECONDATA"
  }
  if (!is.null(params$version)) {
    version  <- params$version
  } else {
    version <- "latest"
  }
  if (!is.null(params$release)) {
    release <- params$release
  } else {
    release <- "latest"
  }
  env <- fromJSON(system.file("settings.json", package = "econdatar"))
  if (nchar(Sys.getenv("ECONDATA_URL")) != 0) {
    env$repository$url <- Sys.getenv("ECONDATA_URL")
    env$registry$url <- Sys.getenv("ECONDATA_URL")
  }
  if (nchar(Sys.getenv("ECONDATA_AUTH_URL")) != 0) {
    env$auth$url <- Sys.getenv("ECONDATA_AUTH_URL")
  }


  # Fetch data set(s) ----

  message(paste("\nFetching data set(s) -", id, "\n"))
  if (!is.null(params$file)) {
    data_message <- fromJSON(params$file, simplifyVector = FALSE)
    data_message[[2]]$`data-sets` <-
      lapply(data_message[[2]]$`data-sets`, function(x) {
        x[[2]]$name <- lapply(x[[2]]$name, unlist)
        x[[2]]$description <- lapply(x[[2]]$name, unlist)
        return(x)
      })
    message("Data set(s) successfully retrieved from local storage.\n")
  } else {
    if (exists("econdata_token", envir = .pkgenv)) {
      token <- unlist(strsplit(get("econdata_token", envir = .pkgenv), " "))[2]
      payload <- jwt_split(token)$payload
      if (Sys.time() > as.POSIXct(payload$exp, origin = "1970-01-01")) {
        login_helper(env$auth)
      }
    } else {
      login_helper(env$auth)
    }
    query_params <- list()
    query_params$agencyids <- paste(agencyid, collapse = ",")
    query_params$ids <- paste(id, collapse = ",")
    query_params$versions <- paste(version, collapse = ",")
    response <- GET(env$repository$url,
                    path = c(env$repository$path, "/datasets"),
                    query = query_params,
                    add_headers(authorization = get("econdata_token",
                                                    envir = .pkgenv)),
                    accept("application/vnd.sdmx-codera.data+json"))
    if (params$debug) {
      message("Request URL: ", response$request$url, "\n")
    }
    if (response$status_code != 200) {
      stop(content(response, type = "application/json"))
    }
    data_message <- content(response, type = "application/json")
  }


  # Process data sets ----

  database <- lapply(data_message[[2]][["data-sets"]], function(raw_data_set) {
    if (!is.null(params$file)) {
      tmp_data_set <- raw_data_set[[2]]
    } else {
      data_set_ref <- paste(raw_data_set[[2]]$agencyid,
                            raw_data_set[[2]]$id,
                            raw_data_set[[2]]$version,
                            sep = "-")
      query_params <- list()
      query_params$release <- get_release(env,
                                          data_set_ref,
                                          release,
                                          params$debug)
      if (!is.null(params$series_key)) {
        query_params[["series-key"]] <- params$series_key
      }
      if (!is.null(params$start_date)) {
        query_params[["start"]] <- as.Date(params$start_date) |>
          format("%Y-%m-%d") |>
          as.character()
      }
      if (!is.null(params$end_date)) {
        query_params[["end"]] <- as.Date(params$end_date) |>
          format("%Y-%m-%d") |>
          as.character()
      }
      if (!is.null(params$hist_obs)) {
        if (tidy && params$hist_obs) {
          warning("tidy = TRUE, hist_obs = TRUE incompatible, set tidy = FALSE")
          tidy <- FALSE
        }
        query_params[["hist-obs"]] <- if (params$hist_obs) "true" else "false"
      }
      tmp_data_set <- get_data(env,
                               data_set_ref,
                               query_params,
                               debug = params$debug)
    }
    series_names <- sapply(tmp_data_set$series, function(raw_series) {
      return(raw_series[["series-key"]])
    })
    data_set <- lapply(tmp_data_set$series, function(raw_series) {
      obs <- raw_series$obs
      raw_series[["series-key"]] <- NULL
      raw_series[["obs"]] <- NULL
      if (length(obs) == 0) {
        series <- data.frame()
        attr(series, "metadata") <- raw_series
        return(series)
      } else {
        fields <- lapply(obs, function(x) names(x)) |>
          unlist() |>
          unique()
        series <- lapply(fields, function(n) {
          sapply(obs, function(x) {
            ifelse(is.null(x[[n]]), NA, x[[n]])
          })
        }) |>
          as.data.frame(col.names = fields)
        if (is.null(params$hist_obs) || !params$hist_obs) {
          rownames(series) <- series$TIME_PERIOD
          series$TIME_PERIOD <- NULL
        }
        attr(series, "metadata") <- raw_series
        return(series)
      }
    })
    names(data_set) <- series_names
    tmp_data_set$series <- NULL
    attr(data_set, "metadata") <- tmp_data_set
    class(data_set) <- "eds_dataset"
    return(data_set)
  })
  class(database) <- "eds_database"
  if (length(database) == 1) {
    return(if (tidy) tidy_data(database[[1]], ...) else database[[1]])
  } else {
    return(if (tidy) tidy_data(database, ...) else database)
  }
}

read_econdata <- function(id, tidy = FALSE, ...) {
  .Deprecated("read_dataset")
  read_dataset(id, tidy = tidy, ...)
}

get_release <- function(env, ref, candidate_release, debug = FALSE) {
  if (candidate_release != "unreleased") {
    chosen_release <- tryCatch({
      if (grepl("^\\d{4}-\\d{1,2}-\\d{1,2}(T\\d{1,2}:\\d{1,2}:\\d{1,2})?$",
                candidate_release,
                perl = TRUE)) {
        release <- as.POSIXct(candidate_release, format = "%Y-%m-%dT%H:%M:%S")
        return(strftime(release,
                        format = "%Y-%m-%dT%H:%M:%S",
                        tz = "Africa/Johannesburg"))
      } else {
        stop("Unacceptable proposed time/date format")
      }
    }, error = function(e) {
      response <- GET(env$repository$url,
                      path = paste(env$repository$path,
                                   "datasets",
                                   ref,
                                   "release", sep = "/"),
                      add_headers(authorization = get("econdata_token",
                                                      envir = .pkgenv)),
                      accept_json())
      if (debug) {
        message("Request URL: ", response$request$url, "\n")
      }
      if (response$status_code != 200) {
        stop(content(response, type = "application/json"))
      }
      data_message <- content(response, type = "application/json")
      if (length(data_message$releases) != 0) {
        if (candidate_release == "latest") {
          release <- head(data_message$releases, n = 1)[[1]]$release |>
            as.POSIXct(tz = "UTC", format = "%Y-%m-%dT%H:%M:%S")
          return(strftime(release,
                          format = "%Y-%m-%dT%H:%M:%S",
                          tz = "Africa/Johannesburg"))
        } else {
          release <- sapply(data_message$releases, function(release) {
            if (candidate_release == release$description) {
              release$release
            } else {
              NA
            }
          }) |>
            na.omit() |>
            head(n = 1)
          if (length(release) != 0) {
            release <- as.POSIXct(release,
                                  tz = "UTC",
                                  format = "%Y-%m-%dT%H:%M:%S")
            return(strftime(release,
                            format = "%Y-%m-%dT%H:%M:%S",
                            tz = "Africa/Johannesburg"))
          } else {
            message("Release not found, returning latest release instead.")
            release <- tail(data_message$releases, n = 1)[[1]]$release |>
              as.POSIXct(tz = "UTC", format = "%Y-%m-%dT%H:%M:%S")
            return(strftime(release,
                            format = "%Y-%m-%dT%H:%M:%S",
                            tz = "Africa/Johannesburg"))
          }
        }
      } else {
        stop("Data set has no historical releases, ",
             "try: release = \"unreleased\"")
      }
    })
  } else {
    chosen_release <- NULL
  }
  return(chosen_release)
}

get_data <- function(
  env,
  ref,
  params,
  series_key = NULL,
  links = NULL,
  data_set = NULL,
  debug = FALSE
) {
  if (is.null(links)) {
    if (is.null(series_key)) {
      if (!is.null(params[["series-key"]]) &&
            length(params[["series-key"]]) > 0) {
        series_key <- params[["series-key"]]
        params[["series-key"]] <- series_key[1]
        series_key <- if (length(series_key) > 1) series_key[-1L] else NULL
      }
      response <- GET(env$repository$url,
                      path = paste(env$repository$path,
                                   "datasets",
                                   ref, sep = "/"),
                      query = params,
                      add_headers(authorization = get("econdata_token",
                                                      envir = .pkgenv)),
                      accept("application/vnd.sdmx-codera.data+json"))
      if (debug) {
        message("Request URL: ", response$request$url, "\n")
      }
      if (response$status_code == 200) {
        message("Processing data set: ", ref, "\n")
      } else {
        stop(content(response, type = "application/json"))
      }
      links <- unlist(strsplit(response$headers$link, ","))
      data_message <- content(response, type = "application/json")
      data_set <- data_message[[2]][["data-sets"]][[1]][[2]]
      if (is.null(series_key) && !any(grepl("rel=next", links))) {
        # Done
        return(data_set)
      } else if (!is.null(series_key) && !any(grepl("rel=next", links))) {
        # Go to next in series_key
        return(get_data(env, ref, params, series_key, NULL, data_set, debug))
      } else {
        # Go to next link
        return(get_data(env, ref, params, series_key, links, data_set, debug))
      }
    } else {
      params[["series-key"]] <- series_key[1]
      series_key <- if (length(series_key) > 1) series_key[-1L] else NULL
      response <- GET(env$repository$url,
                      path = paste(env$repository$path,
                                   "datasets",
                                   ref, sep = "/"),
                      query = params,
                      add_headers(authorization = get("econdata_token",
                                                      envir = .pkgenv)),
                      accept("application/vnd.sdmx-codera.data+json"))
      if (debug) {
        message("Request URL: ", response$request$url, "\n")
      }
      if (response$status_code != 200) {
        stop(content(response, type = "application/json"))
      }
      data_message <- content(response, type = "application/json")
      data_set$series <- c(data_set$series,
                           data_message[[2]][["data-sets"]][[1]][[2]]$series)
      if (is.null(series_key) && !any(grepl("rel=next", links))) {
        # Done
        return(data_set)
      } else if (!is.null(series_key) && !any(grepl("rel=next", links))) {
        # Go to next in series_key
        return(get_data(env, ref, params, series_key, NULL, data_set, debug))
      } else {
        # Go to next link
        return(get_data(env, ref, params, series_key, links, data_set, debug))
      }
    }
  } else {
    link_next <- links[grepl("rel=next", links)]
    link_match <- regexec("^(<)(.+)(>;rel=next)$", link_next)
    link_parts <- regmatches(link_next, link_match)[[1]][3] |>
      URLdecode() |>
      strsplit("\\?") |>
      unlist()
    response <-
      GET(env$repository$url,
          path = link_parts[1],
          query = strsplit(unlist(strsplit(link_parts[2], "&")), "=") |>
            lapply(function(x) {
              y <- list()
              y[[x[1]]] <- x[2]
              return(y)
            }) |>
            unlist(recursive = FALSE),
          add_headers(authorization = get("econdata_token", envir = .pkgenv)),
          accept("application/vnd.sdmx-codera.data+json"))
    if (debug) {
      message("Request URL: ", response$request$url, "\n")
    }
    if (response$status_code != 200) {
      stop(content(response, type = "application/json"))
    }
    links <- unlist(strsplit(response$headers$link, ","))
    data_message <- content(response, type = "application/json")
    data_set$series <- c(data_set$series,
                         data_message[[2]][["data-sets"]][[1]][[2]]$series)
    if (is.null(series_key) && !any(grepl("rel=next", links))) {
      # Done
      return(data_set)
    } else if (!is.null(series_key) && !any(grepl("rel=next", links))) {
      # Go to next in series_key
      return(get_data(env, ref, params, series_key, NULL, data_set, debug))
    } else {
      # Go to next link
      return(get_data(env, ref, params, series_key, links, data_set, debug))
    }
  }
}

read_registry <- function(structure, tidy = TRUE, ...) {


  # Parameters ----

  params <- list(...)
  if (is.null(params$id) && is.null(params$file)) {
    stop("At least one of either: 'id' or 'file' parameter required.")
  }
  if (!is.null(params$agencyid)) {
    agencyid  <- params$agencyid
  } else {
    agencyid <- "ECONDATA"
  }
  if (!is.null(params$id)) {
    id  <- params$id
  } else {
    id <- NULL
  }
  if (!is.null(params$version)) {
    version  <- params$version
  } else {
    version <- "latest"
  }
  env <- fromJSON(system.file("settings.json", package = "econdatar"))
  if (nchar(Sys.getenv("ECONDATA_URL")) != 0) {
    env$repository$url <- Sys.getenv("ECONDATA_URL")
    env$registry$url <- Sys.getenv("ECONDATA_URL")
  }
  if (nchar(Sys.getenv("ECONDATA_AUTH_URL")) != 0) {
    env$auth$url <- Sys.getenv("ECONDATA_AUTH_URL")
  }
  params$env <- env


  # Fetch structure(s) ----

  if (is.null(params$file)) {
    if (exists("econdata_token", envir = .pkgenv)) {
      token <- unlist(strsplit(get("econdata_token", envir = .pkgenv), " "))[2]
      payload <- jwt_split(token)$payload
      if (Sys.time() > as.POSIXct(payload$exp, origin="1970-01-01")) {
        login_helper(env$auth)
      }
    } else {
      login_helper(env$auth)
    }
  }
  agencyids <- paste(agencyid, collapse = ",")
  ids <- paste(id, collapse = ",")
  versions <- paste(version, collapse = ",")
  structure_data <-
    switch(structure,
           "agency-scheme" =
           read_agency_schemes(agencyids, ids, versions, params),
           "category-scheme" =
           read_category_schemes(agencyids, ids, versions, params),
           "codelist" =
           read_codelists(agencyids, ids, versions, params),
           "concept-scheme" =
           read_concept_schemes(agencyids, ids, versions, params),
           "data-consumer-scheme" =
           read_data_consumer_schemes(agencyids, ids, versions, params),
           "data-provider-scheme" =
           read_data_provider_schemes(agencyids, ids, versions, params),
           "dataflow" =
           read_dataflows(agencyids, ids, versions, params),
           "data-structure" =
           read_data_structures(agencyids, ids, versions, params),
           "memberlist" =
           read_memberlist(agencyids, ids, versions, params),
           "consumption-agreement" =
           read_cons_agreement(agencyids, ids, versions, params),
           "provision-agreement" =
           read_prov_agreement(agencyids, ids, versions, params),
           stop("Specified structure, ", structure, ", is not supported."))


  # Process structures ----

  structures <- lapply(structure_data, function(x) {
    switch(structure,
           "agency-scheme" = process_agency_scheme(x, params),
           "category-scheme" = process_category_scheme(x, params),
           "codelist" = process_codelist(x, params),
           "concept-scheme" = process_concept_scheme(x, params),
           "data-consumer-scheme" = process_data_consumer_scheme(x, params),
           "data-provider-scheme" = process_data_provider_scheme(x, params),
           "dataflow" = process_dataflow(x, params),
           "data-structure" = process_data_structure(x, params),
           "memberlist" = process_memberlist(x, params),
           "consumption-agreement" = process_cons_agreement(x, params),
           "provision-agreement" = process_prov_agreement(x, params),
           stop("Specified structure, ", structure, ", is not supported."))
  })
  if (length(structures) == 1) {
    return(structures[[1]])
  } else {
    return(structures)
  }
}



# Agency schemes ----


read_agency_schemes <- function(agencyids, ids, versions, params) {
  if (is.null(params$file)) {
    message(paste("\nFetching agency scheme(s) -",
                  paste(ids, collapse = ", "), "\n"))
    response <- GET(params$env$registry$url,
                    path = paste(c(params$env$registry$path, "agencyschemes"),
                                 collapse = "/"),
                    query = list(agencyids = agencyids,
                                 ids = ids,
                                 versions = versions),
                    add_headers(authorization = get("econdata_token",
                                                    envir = .pkgenv)),
                    accept("application/vnd.sdmx-codera.data+json"))
    if (response$status_code != 200) {
      stop(content(response, type = "application/json"))
    }
    data_message <- content(response, type = "application/json")
    agency_schemes <- data_message[[2]][["structures"]][["agency-schemes"]]
    return(agency_schemes)
  } else {
    message(paste("\nFetching agency scheme(s) -", params$file, "\n"))
    na <- c("", "NA", "#N/A")
    agencies <- read_ods(path = params$file,
                         sheet = "agencies",
                         na = na,
                         as_tibble = FALSE)
    agency_scheme <- as.list(read_ods(path = params$file,
                                      sheet = "agency_scheme",
                                      na = na,
                                      as_tibble = FALSE))
    agency_scheme$agencies <- agencies
    return(list(agency_scheme))
  }
}

process_agency_scheme <- function(structure, params) {
  if (is.null(params$file)) {
    structure_ref <- paste(structure[[2]]$agencyid,
                           structure[[2]]$id,
                           structure[[2]]$version,
                           sep = "-")
    message("Processing agency scheme: ", structure_ref, "\n")
    description <- if (is.null(structure[[2]]$description[[2]])) {
      NA
    } else {
      structure[[2]]$description[[2]]
    }
    agency_scheme <- list(agencyid = structure[[2]]$agencyid,
                          id = structure[[2]]$id,
                          version = structure[[2]]$version,
                          name = structure[[2]]$name[[2]],
                          description = description)
    agencies <- lapply(structure[[2]]$agencies, function(agency) {
      description <- if (is.null(agency[[2]]$description[[2]])) {
        NA
      } else {
        agency[[2]]$description[[2]]
      }
      if (length(agency[[2]]$contacts) == 0) {
        list(id = agency[[2]]$id,
             name = agency[[2]]$name[[2]],
             description = description,
             contact_name = NA,
             contact_department = NA,
             contact_email = NA)
      } else {
        lapply(agency[[2]]$contacts, function(contact) {
          department <- if (is.null(contact$department[[2]])) {
            NA
          } else {
            contact$department[[2]]
          }
          email <- if (is.null(contact$email)) {
            NA
          } else {
            contact$email
          }
          list(id = agency[[2]]$id,
               name = agency[[2]]$name[[2]],
               description = description,
               contact_name = contact$name[[2]],
               contact_department = department,
               contact_email = email)
        }) |>
          do.call(rbind.data.frame, args = _)
      }
    }) |>
    do.call(rbind.data.frame, args = _)
  agency_scheme$agencies <- agencies
  class(agency_scheme) <- c(class(agency_scheme), "eds_agency_scheme")
  return(agency_scheme)
  } else {
    message("Processing agency scheme: ", params$file, "\n")
    class(structure) <- c(class(structure), "eds_agency_scheme")
    return(structure)
  }
}



